{
  "name": "bt_save_conn_info",
  "confidence": "medium",
  "docstring": "Persists per-connection state by writing a sub_12dd88 lookup result derived from the connection handle at offset 364 into a global, adjusting an elapsed-time counter at v2[-8] with a decrement-plus-handle delta, and zeroing a scratch field at v2[-1], while consulting bt_get_link_state as a side-effect.",
  "subsystem": "bt",
  "var_renames": {
    "v1": "conn_info_state",
    "v2": "timer_counter_base",
    "a1": "conn_entry"
  },
  "struct_hints": [
    {"offset": 364, "meaning": "conn_handle or conn_interval (uint16_t) within connection entry"},
    {"offset": -12, "meaning": "previous elapsed-tick reference (uint32_t) before v2"},
    {"offset": -8, "meaning": "adjusted timeout / elapsed counter slot (uint32_t)"}
  ]
}
